static sgre::scene::EmoteCollisionEllipse ReadContactEllipse(const std::array<std::uint32_t, 16>& row, std::size_t offset) {
	sgre::scene::EmoteCollisionEllipse result;
	result.Center = {std::bit_cast<float>(row[offset]), std::bit_cast<float>(row[offset + 1])};
	result.Radius = {std::bit_cast<float>(row[offset + 2]), std::bit_cast<float>(row[offset + 3])};
	result.Rotation = std::bit_cast<float>(row[offset + 4]);

	return result;
}

static void TestNativeContactCoefficients() {
	for (const auto& row : kNativeContacts) {
		const auto particle = ReadContactEllipse(row, 2);
		const auto collider = ReadContactEllipse(row, 7);
		const sgre::resource::MotionPoint displacement{std::bit_cast<float>(row[0]), std::bit_cast<float>(row[1])};
		std::size_t remaining = 4096;
		sgre::resource::MotionPoint projected;
		const bool contact = sgre::scene::ProjectEmoteEllipseContact(projected, particle, displacement, collider, row[12] != 0, remaining);
		Require(contact == (row[13] != 0), "actual native section contact decision changed");
		if (contact) {
			Require(std::bit_cast<std::uint32_t>(projected.X) == row[14] && std::bit_cast<std::uint32_t>(projected.Y) == row[15], "actual native contact must retain transformed conic coefficients through principal-axis recovery");
		}
	}

	auto particle = ReadContactEllipse(kNativeContacts[0], 2);
	const auto collider = ReadContactEllipse(kNativeContacts[0], 7);
	particle.Radius.X = 0;
	std::size_t remaining = 4096;
	sgre::resource::MotionPoint projected;
	bool rejected = false;
	try {
		static_cast<void>(sgre::scene::ProjectEmoteEllipseContact(projected, particle, {}, collider, true, remaining));
	} catch (const std::runtime_error&) {
		rejected = true;
	}
	Require(rejected, "signed native section admission must still reject a zero horizontal axis");
}

int main() {
	try {
		for (const auto& row : kNativeWords) {
			const auto first = std::bit_cast<float>(row[1]);
			const auto second = std::bit_cast<float>(row[2]);
			float result = 0;
			switch (row[0]) {
			case 0:
				result = sgre::scene::PrepareEmotePhysicalSine(first);
				break;
			case 1:
				result = sgre::scene::PrepareEmotePhysicalCosine(first);
				break;
			case 2:
				result = sgre::scene::PrepareEmotePhysicalAngle(first, second);
				break;
			case 3:
				result = sgre::scene::PrepareEmotePhysicalArcCosine(first);
				break;
			default:
				throw std::runtime_error("unknown original primitive vector");
			}
			Require(std::bit_cast<std::uint32_t>(result) == row[3], "Emote physical primitive differs from its unchanged original word");
		}
		TestNativeContactCoefficients();
		const auto unordered = std::numeric_limits<float>::quiet_NaN();
		Require(std::isnan(sgre::scene::PrepareEmotePhysicalAngle(unordered, 0)), "unordered comparison must retain a NaN angle");
		Require(std::isnan(sgre::scene::PrepareEmotePhysicalArcCosine(unordered)), "unordered comparison must retain a NaN arccosine");
		Require(std::isnan(sgre::scene::PrepareEmotePhysicalArcCosine(2)), "out-of-domain arccosine must retain its existing NaN result");
		std::cout << kNativeWords.size() << " original Emote physical math words and 75 exact contact cases PASS\n";

		return 0;
	} catch (const std::exception& error) {
		std::cerr << error.what() << '\n';

		return 1;
	}
}
